package com.hmdp.ai.runtime.retrieval;
import com.hmdp.ai.domain.knowledge.IndexHit;import org.springframework.stereotype.Component;import java.util.*;
@Component public class RrfFusionRanker {public List<FusedHit> fuse(List<List<IndexHit>> rankings,int k){Map<String,Mutable> values=new LinkedHashMap<>();for(int source=0;source<rankings.size();source++){List<IndexHit> list=rankings.get(source);for(int rank=0;rank<list.size();rank++){IndexHit hit=list.get(rank);Mutable value=values.computeIfAbsent(hit.getChunkId(),id->new Mutable(id));value.score+=1.0/(Math.max(1,k)+rank+1);if(source%2==0)value.vector=Math.max(value.vector,hit.getScore());else value.lexical=Math.max(value.lexical,hit.getScore());}}List<FusedHit> result=new ArrayList<>();for(Mutable value:values.values())result.add(new FusedHit(value.id,value.score,value.vector,value.lexical));result.sort(Comparator.comparingDouble(FusedHit::getScore).reversed().thenComparing(FusedHit::getChunkId));return result;}private static final class Mutable{private final String id;private double score,vector,lexical;private Mutable(String id){this.id=id;}}public static final class FusedHit{private final String chunkId;private final double score,vectorScore,lexicalScore;public FusedHit(String chunkId,double score,double vectorScore,double lexicalScore){this.chunkId=chunkId;this.score=score;this.vectorScore=vectorScore;this.lexicalScore=lexicalScore;}public String getChunkId(){return chunkId;}public double getScore(){return score;}public double getVectorScore(){return vectorScore;}public double getLexicalScore(){return lexicalScore;}}}
